<div class="water-balance-grid"><article class="panel p-4"><div class="panel-head"><div><h3>Neraca Debit Master</h3><p>Berdasarkan debit normal sumber aktif</p></div></div><?php $available=(float)($sourceTotals['normal_flow']??0);$need=(float)$demand;$pct=$need>0?min(100,$available/$need*100):0;?><div class="water-balance"><div><span>Debit tersedia</span><strong><?=number_format($available,2,',','.')?> <small>L/s</small></strong></div><i class="bi bi-arrow-left-right"></i><div><span>Kebutuhan desain</span><strong><?=number_format($need,2,',','.')?> <small>L/s</small></strong></div></div><div class="progress mt-4" style="height:12px"><div class="progress-bar <?=$pct<80?'bg-danger':($pct<100?'bg-warning':'bg-success')?>" style="width:<?=$pct?>%"></div></div><small class="text-secondary d-block mt-2"><?=number_format($pct,1,',','.')?>% kebutuhan tersedia pada data master.</small></article>
<article class="panel p-4"><h3 class="h6">Akses Cepat</h3><div class="water-quick"><a href="<?=url('water-sources')?>"><i class="bi bi-droplet"></i>Kelola sumber</a><a href="<?=url('reservoirs')?>"><i class="bi bi-box"></i>Kelola reservoir</a><a href="<?=url('service-areas')?>"><i class="bi bi-houses"></i>Wilayah layanan</a><a href="<?=url('distribution-networks')?>"><i class="bi bi-share"></i>Jaringan distribusi</a></div></article></div>
<section class="panel mt-3"><div class="panel-title-row"><div><h3>Simulasi Terbaru</h3><p>Hasil perhitungan yang tersimpan sebagai snapshot.</p></div><a href="<?=url('water-results')?>">Lihat semua <i class="bi bi-arrow-right"></i></a></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Nomor</th><th>Nama</th><th>Tanggal</th><th>Debit Efektif</th><th>Kebutuhan</th><th>Selisih</th><th>Terpenuhi</th><th>Status</th></tr></thead><tbody><?php if(!$latest):?><tr><td colspan="8"><div class="empty-state"><i class="bi bi-calculator"></i><h4>Belum ada simulasi</h4><p>Lengkapi data master lalu jalankan simulasi pertama.</p></div></td></tr><?php endif?><?php foreach($latest as $row):?><tr><td><a href="<?=url('water-results/'.$row['id'])?>"><strong><?=e($row['simulation_number'])?></strong></a></td><td><?=e($row['name'])?></td><td><?=e($row['simulation_date'])?></td><td><?=number_format((float)$row['total_effective_flow_lps'],2,',','.')?> L/s</td><td><?=number_format((float)$row['total_demand_lps'],2,',','.')?> L/s</td><td class="<?=$row['surplus_deficit_lps']<0?'text-danger':'text-success'?>"><?=number_format((float)$row['surplus_deficit_lps'],2,',','.')?></td><td><?=number_format((float)$row['fulfillment_percent'],1,',','.')?>%</td><td><span class="water-status <?=$row['result_status']?>"><?=e(ucfirst($row['result_status']??'draft'))?></span></td></tr><?php endforeach?></tbody></table></div></section>

